const $=id=>document.getElementById(id);let feed=[],mode='proposals',checking=false,lastStatus='';const date=s=>new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
function render(){const parent=$('newsFeed');parent.replaceChildren();if(mode==='news'){const msg=document.createElement('div');msg.className='empty';msg.textContent='The news and announcements feed is not connected yet.';parent.append(msg);return}if(!feed.length){const msg=document.createElement('div');msg.className='empty';msg.textContent='No proposal records available. Use the source link to check NEAR’s repository.';parent.append(msg);return}for(const item of [...feed].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt))){const article=document.createElement('article');article.className='news-item';const meta=document.createElement('div');meta.className='news-type';meta.textContent=(item.draft?'DRAFT':'OPEN PROPOSAL')+' · NEAR / NEPs';const h=document.createElement('h2');h.textContent=item.title;const time=document.createElement('div');time.className='news-time';time.textContent='Opened '+date(item.createdAt)+' · Updated '+date(item.updatedAt);const actions=document.createElement('div');actions.className='news-actions';actions.style.marginTop='15px';const link=document.createElement('a');link.textContent='Read proposal ↗';try{const url=new URL(item.url);if(url.origin!=='https://github.com'||!url.pathname.startsWith('/near/NEPs/pull/'))continue;link.href=url.href;}catch{continue}link.target='_blank';link.rel='noopener';actions.append(link);article.append(meta,h,time,actions);parent.append(article);}}
async function refresh(){if(checking)return;checking=true;$('refreshFeed').disabled=true;$('feedStatus').textContent='Checking proposals…';try{const r=await fetch('https://api.github.com/repos/near/NEPs/pulls?state=open&sort=updated&direction=desc&per_page=20',{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Feed unavailable');const data=await r.json();if(!Array.isArray(data))throw Error('Invalid feed');feed=data.map(x=>({title:x.title,url:x.html_url,createdAt:x.created_at,updatedAt:x.updated_at,draft:x.draft}));lastStatus='Checked '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})+' · NEAR proposals';$('feedStatus').textContent=lastStatus;render();}catch{$('feedStatus').textContent=feed.length?'Saved proposals · live check unavailable':'Live check unavailable';}finally{checking=false;$('refreshFeed').disabled=false;}}
fetch('./data/catalysts.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(j=>{feed=j.items||[];$('feedStatus').textContent='Saved '+date(j.retrievedAt);render();}).catch(()=>render()).finally(refresh);
$('refreshFeed').onclick=refresh;document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{mode=b.dataset.feed;document.querySelectorAll('[data-feed]').forEach(x=>x.classList.toggle('on',x===b));render()});$('explainExample').onclick=()=>$('explanation').showModal();document.querySelector('.close').onclick=()=>$('explanation').close();setInterval(()=>{if(!document.hidden)refresh()},300000);
